import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[][] q = new long[n][2];
        for (int i = 0; i < n; i++) q[i][0] = nextLong();
        for (int i = 0; i < n; i++) q[i][1] = nextLong();
        Arrays.sort(q, (a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        PriorityQueue<Long> h = new PriorityQueue<>();  // last days of open investors
        long day = 0, ans = 0;
        int i = 0;
        while (i < n || !h.isEmpty()) {
            if (h.isEmpty()) day = Math.max(day, q[i][0]);
            while (i < n && q[i][0] <= day) h.add(q[i++][1]);
            while (!h.isEmpty() && h.peek() < day) h.poll();
            if (!h.isEmpty()) {
                h.poll();  // meet the investor whose window closes first
                ans++;
                day++;
            }
        }
        System.out.println(ans);
    }
}

