import (
	"container/heap"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

type minHeap []int64

func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(int64)) }
func (h *minHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	q := make([][2]int64, n)
	for i := range q {
		q[i][0] = nextInt()
	}
	for i := range q {
		q[i][1] = nextInt()
	}
	slices.SortFunc(q, func(a, b [2]int64) int {
		if a[0] != b[0] {
			return int(a[0] - b[0])
		}
		return int(a[1] - b[1])
	})
	h := &minHeap{} // last days of open investors
	var day, ans int64
	i := 0
	for i < n || h.Len() > 0 {
		if h.Len() == 0 {
			day = max(day, q[i][0])
		}
		for i < n && q[i][0] <= day {
			heap.Push(h, q[i][1])
			i++
		}
		for h.Len() > 0 && (*h)[0] < day {
			heap.Pop(h)
		}
		if h.Len() > 0 {
			heap.Pop(h) // meet the investor whose window closes first
			ans++
			day++
		}
	}
	fmt.Println(ans)
}
